BEGIN
  DELETE FROM dbo.IQDayBook WHERE Act_ID=@id AND Div_no=0 AND TRDATE<@fyStart;
  EXEC dbo.IQdaybook_insert @sr_no=@sr OUTPUT, @trdate=@eve, @Act_id=@id, @Amount=@opAmt, @type=@opSign, @Contra_id=0, @BL_Adjusted=0, @Adjusted=0, @Doc_ID=-1,
