  @ent_Uid=1, @adj_id=0, @lnno=0, @mDiscRow='', @MImportCollection_DtldID=0;

/* HQ re-save of one party: the statements FrmAccounts.SaveData issues when an existing account is opened and saved
   (IQaccmst_update -> IQAccAdr delete+insert -> IQAccOthers delete+10 inserts -> opening row -> account 5), with every
   value reloaded the way Fill_EditData/EditAccount load it, plus this repair's overrides. One transaction.
   @fyStart = the firm's FY start ([Company Master]/FY.startdt). */
SET XACT_ABORT ON;
DECLARE @id int = <Act_Id from the finding>;
DECLARE @fyStart datetime = '2026-04-01', @today datetime = CAST(CAST(GETDATE() AS date) AS datetime);
DECLARE @entDate int = CAST(CONVERT(char(8), GETDATE(), 112) AS int);
DECLARE @a TABLE (Act_Name nvarchar(200), Act_Type nvarchar(23), Rec_Higher int, Act_Code nvarchar(60), Act_TT nvarchar(25), Act_OpSplit bit, Act_BillMode int,
  Act_Usage tinyint, Act_ControlID int, Cust_Type tinyint, Bill2Bill tinyint, SalesmanID int, IsStaff tinyint, Shift_ID int, ActTaxType tinyint, IsTCSAPPLY tinyint,
  Act_OPbal numeric(18,2), Act_OpSign nvarchar(1));
INSERT @a SELECT Act_Name, Act_Type, Rec_Higher, Act_Code, Act_TT, ISNULL(Act_OpSplit,0), ISNULL(Act_BillMode,0), ISNULL(Act_Usage,0), ISNULL(Act_ControlID,0),
  ISNULL(Cust_Type,0), ISNULL(Bill2Bill,0), ISNULL(SalesmanID,0), ISNULL(IsStaff,0), ISNULL(Shift_ID,0), ISNULL(ActTaxType,2), ISNULL(IsTCSAPPLY,0),
  ISNULL(Act_OPbal,0), Act_OpSign
  FROM dbo.IQAccmst WHERE Act_Id=@id AND Act_Cat='A' AND Act_Type IN ('Customer','Supplier','Customer-Supplier');
IF @@ROWCOUNT=0 OR @id<=8 RAISERROR('not an editable party account',16,1);
-- opening balance as EditAccount loads it: sum of the account's Doc_Id=-1 rows
DECLARE @open numeric(18,2) = (SELECT ISNULL(SUM(CASE WHEN TYPE IN ('D','d') THEN AMOUNT ELSE -AMOUNT END),0) FROM dbo.IQDayBook WHERE Act_ID=@id AND Doc_ID=-1);
IF (SELECT Act_OpSplit FROM @a)=1 RAISERROR('bill-wise opening balance: re-save in HQ',16,1);
IF (SELECT CASE WHEN Act_OpSign='C' THEN -Act_OPbal ELSE Act_OPbal END FROM @a)<>@open
  RAISERROR('Act_OPbal differs from the opening rows (check P-OPEN-MASTER); a re-save would silently change it',16,1);
-- reloaded address (Fill_EditData trims every box; a missing row loads as blanks, state 37-Andhra Pradesh, GST type 2)
DECLARE @d TABLE (person varchar(200), Add_Line1 varchar(200), Add_Line2 varchar(200), Act_Town varchar(200), Act_District varchar(200), Act_state varchar(100),
  Act_PinNo varchar(50), Act_Ph1 varchar(50), Act_Ph2 varchar(50), Act_STD varchar(50), Act_Cell varchar(50), Act_Email varchar(100), Act_CSTNo varchar(100),
  Act_SSTNo varchar(100), Act_Credit float, Act_CrDays int, Act_PAN varchar(50), Act_TAN varchar(100), Area_Id int, Act_Transport varchar(100), Act_VAT_TINNO varchar(100),
  Act_Rate numeric(18,2), Act_DL20B varchar(50), Act_DL21B varchar(50), ship_Person varchar(100), ship_Add_Line1 varchar(200), ship_Add_Line2 varchar(200),
  ship_Act_Town varchar(100), ship_Act_District varchar(100), ship_Act_state varchar(100), ship_Act_PinNo varchar(50), ship_Act_Ph1 varchar(50), ship_Act_Ph2 varchar(50),
  ship_Act_STD varchar(50), ship_Act_Cell varchar(50), ship_Act_Email varchar(100), AadharNo varchar(50), GSTIN varchar(50), GSTTaxType tinyint, ship_Act_GSIN varchar(60),
  ship_Act_PANNO varchar(60), Act_CrCtrlDays smallint, ActFoodLICNO varchar(100), Note1 varchar(500), Note2 varchar(500), Note3 varchar(500), Note4 varchar(500),
  Note5 varchar(500), Note6 varchar(500), Image1 varchar(500), Image2 varchar(500), Image3 varchar(500), Image4 varchar(500));
INSERT @d SELECT
  LTRIM(RTRIM(ISNULL(r.person,''))), LTRIM(RTRIM(ISNULL(r.Add_Line1,''))), LTRIM(RTRIM(ISNULL(r.Add_Line2,''))), LTRIM(RTRIM(ISNULL(r.Act_Town,''))),
  LTRIM(RTRIM(ISNULL(r.Act_District,''))), CASE WHEN LTRIM(RTRIM(ISNULL(r.Act_state,'')))='' THEN '37-Andhra Pradesh' ELSE LTRIM(RTRIM(r.Act_state)) END,
  LTRIM(RTRIM(ISNULL(r.Act_PinNo,''))), LTRIM(RTRIM(ISNULL(r.Act_Ph1,''))), LTRIM(RTRIM(ISNULL(r.Act_Ph2,''))), LTRIM(RTRIM(ISNULL(r.Act_STD,''))),
  LTRIM(RTRIM(ISNULL(r.Act_Cell,''))), LTRIM(RTRIM(ISNULL(r.Act_Email,''))), LTRIM(RTRIM(ISNULL(r.Act_CSTNo,''))), LTRIM(RTRIM(ISNULL(r.Act_SSTNo,''))),
  ISNULL(r.Act_Credit,0), ISNULL(CASE WHEN ISNUMERIC(r.Act_CrDays)=1 THEN CAST(LTRIM(RTRIM(r.Act_CrDays)) AS int) END,0),
  LTRIM(RTRIM(ISNULL(r.Act_PAN,''))), LTRIM(RTRIM(ISNULL(r.Act_TAN,''))), ISNULL(r.Area_Id,0), LTRIM(RTRIM(ISNULL(r.Act_Transport,''))),
  LTRIM(RTRIM(ISNULL(r.Act_VAT_TINNO,''))), CASE WHEN ISNULL(r.Act_Rate,0)<=0 THEN 1 ELSE FLOOR(r.Act_Rate) END,
  LTRIM(RTRIM(ISNULL(r.Act_DL20B,''))), LTRIM(RTRIM(ISNULL(r.Act_DL21B,''))), LTRIM(RTRIM(ISNULL(r.ship_Person,''))), LTRIM(RTRIM(ISNULL(r.ship_Add_Line1,''))),
  LTRIM(RTRIM(ISNULL(r.ship_Add_Line2,''))), LTRIM(RTRIM(ISNULL(r.ship_Act_Town,''))), LTRIM(RTRIM(ISNULL(r.ship_Act_District,''))),
  CASE WHEN LTRIM(RTRIM(ISNULL(r.ship_Act_state,'')))='' THEN '37-Andhra Pradesh' ELSE LTRIM(RTRIM(r.ship_Act_state)) END,
  LTRIM(RTRIM(ISNULL(r.ship_Act_PinNo,''))), LTRIM(RTRIM(ISNULL(r.ship_Act_Ph1,''))), ISNULL(r.ship_Act_Ph2,''), LTRIM(RTRIM(ISNULL(r.ship_Act_STD,''))),
  LTRIM(RTRIM(ISNULL(r.ship_Act_Cell,''))), LTRIM(RTRIM(ISNULL(r.ship_Act_Email,''))), LTRIM(RTRIM(ISNULL(r.AadharNo,''))), UPPER(LTRIM(RTRIM(ISNULL(r.GSTIN,'')))),
  ISNULL(r.GSTTaxType,2), LTRIM(RTRIM(ISNULL(r.ship_Act_GSIN,''))), LTRIM(RTRIM(ISNULL(r.ship_Act_PANNO,''))), ISNULL(r.Act_CrCtrlDays,0),
  LTRIM(RTRIM(ISNULL(r.ActFoodLICNO,''))), LTRIM(RTRIM(ISNULL(r.Act_Note1,''))), LTRIM(RTRIM(ISNULL(r.Act_Note2,''))), LTRIM(RTRIM(ISNULL(r.Act_Note3,''))),
  LTRIM(RTRIM(ISNULL(r.Act_Note4,''))), LTRIM(RTRIM(ISNULL(r.Act_Note5,''))), LTRIM(RTRIM(ISNULL(r.Act_Note6,''))), LTRIM(RTRIM(ISNULL(r.Act_Image1,''))),
  LTRIM(RTRIM(ISNULL(r.Act_Image2,''))), LTRIM(RTRIM(ISNULL(r.Act_Image3,''))), LTRIM(RTRIM(ISNULL(r.Act_Image4,'')))
FROM (SELECT 1 one) o LEFT JOIN dbo.IQAccAdr r ON r.Act_Id=@id;
/* ---------------- repair overrides: what the operator would change in the form ---------------- */
UPDATE @d SET Act_state = st.cap FROM @d CROSS JOIN (VALUES ('01-Jammu & Kashmir'),('02-Himachal Pradesh'),('03-Punjab'),('04-Chandigarh'),('05-Uttarakhand'),('06-Haryana'),('07-Delhi'),('08-Rajasthan'),('09-Uttar Pradesh'),('10-Bihar'),('11-Sikkim'),('12-Arunachal Pradesh'),('13-Nagaland'),('14-Manipur'),('15-Mizoram'),('16-Tripura'),('17-Meghalaya'),('18-Assam'),('19-West Bengal'),('20-Jharkhand'),('21-Odisha'),('22-Chhattisgarh'),('23-Madhya Pradesh'),('24-Gujarat'),('25-Daman & Diu'),('26-Dadra & Nagar Haveli'),('27-Maharashtra'),('29-Karnataka'),('30-Goa'),('31-Lakshdweep'),('32-Kerala'),('33-Tamil Nadu'),('34-Pondicherry'),('35-Andaman & Nicobar Islands'),('36-Telangana'),('37-Andhra Pradesh'),('97-Other Territory')) st(cap) WHERE LEFT(st.cap,2)=LEFT(GSTIN,2) AND LEN(GSTIN)=15 AND GSTTaxType<=1;
