DECLARE @o TABLE (ln int, dg varchar(100), nm varchar(100), ph varchar(100), em varchar(100));
INSERT @o SELECT v.n, LTRIM(RTRIM(ISNULL(x.ActDegn,''))), LTRIM(RTRIM(ISNULL(x.ActName,''))), LTRIM(RTRIM(ISNULL(x.ActPhone,''))), LTRIM(RTRIM(ISNULL(x.ActEmailID,'')))
