DECLARE @ln int = 0, @odg varchar(100), @onm varchar(100), @oph varchar(100), @oem varchar(100);
WHILE @ln < 10
BEGIN
  SELECT @odg=dg, @onm=nm, @oph=ph, @oem=em FROM @o WHERE ln=@ln;
  EXEC dbo.IQAccOthers_insert @mActID=@id, @mActDegn=@odg, @mActName=@onm, @mActPhone=@oph, @mActEmailID=@oem, @mLnNo=@ln;
  SET @ln += 1;
