/* ---------------- 7-8. opening row: HQ deletes + re-inserts (even 0); if payments are settled against it, keep it in place (MK engine rule) ---------------- */
DECLARE @eve datetime = DATEADD(day,-1,@fyStart), @sr bigint;
IF EXISTS (SELECT 1 FROM dbo.IQDayBook b JOIN dbo.ADJUST j ON b.SR_NO IN (j.Sr_No, j.Rel_Sr_No) WHERE b.Act_ID=@id AND b.Doc_ID=-1)
  UPDATE dbo.IQDayBook SET AMOUNT=@opAmt, TYPE=@opSign WHERE Act_ID=@id AND Doc_ID=-1;
ELSE
BEGIN
  DELETE FROM dbo.IQDayBook WHERE Act_ID=@id AND Div_no=0 AND TRDATE<@fyStart;
  EXEC dbo.IQdaybook_insert @sr_no=@sr OUTPUT, @trdate=@eve, @Act_id=@id, @Amount=@opAmt, @type=@opSign, @Contra_id=0, @BL_Adjusted=0, @Adjusted=0, @Doc_ID=-1,
    @VType='opbal', @ARS=0, @ARS_Ord=0, @Div_no=0, @days_from=0, @days_to=0, @int_credit=0, @Tseries='', @Tno=0, @Textn='', @discount=0, @doc_type=0, @Narration='',
    @Bill_Qty=0, @ent_Uid=1, @adj_id=0, @lnno=0, @mDiscRow='', @MImportCollection_DtldID=0;
END;
/* ---------------- 9-12. account 5 "Opening Balance Difference": rewritten on every account save ---------------- */
DECLARE @net numeric(18,2) = (SELECT ISNULL(SUM(CASE WHEN d.TYPE IN ('D','d') THEN d.AMOUNT ELSE -d.AMOUNT END),0) FROM dbo.IQDayBook d JOIN dbo.IQAccMst m ON d.Act_ID=m.Act_ID
  WHERE d.TYPE IN ('D','d','C','c') AND m.Act_ID<>5 AND d.Doc_ID=-1);
DECLARE @dAmt numeric(18,2) = ABS(@net), @dSide varchar(1) = CASE WHEN @net>0 THEN 'C' ELSE 'D' END;
UPDATE dbo.IQAccMst SET Act_Opbal=@dAmt, Act_opSign=@dSide WHERE Act_Id=5;
DELETE FROM dbo.IQDayBook WHERE Div_no=0 AND Act_Id=5;
EXEC dbo.IQdaybook_insert @sr_no=@sr OUTPUT, @trdate=@eve, @Act_id=5, @Amount=@dAmt, @type=@dSide, @Contra_id=0, @BL_Adjusted=0, @Adjusted=0, @Doc_ID=-1, @VType='opDif',
